function morphPoints(o, u){ const w = o._warp; if(!w) return null; const p = Object.assign({}, w.p); KEYS.forEach(k=>{ p[k] = (w.p[k] || 0) * u; }); return outline(w.src).map(q=> warpPt(q, p, w.src.w / 2, w.src.h / 2)); }
