  const loc = pts.map(p=> fabric.util.transformPoint(new fabric.Point(p.x, p.y), inv));
  const xs = loc.map(p=>p.x), ys = loc.map(p=>p.y), cx = (Math.min(...xs) + Math.max(...xs)) / 2, cy = (Math.min(...ys) + Math.max(...ys)) / 2;
