/* ---- colours & fonts ---- */
function normHex(h) { h = h.replace('#', '').toLowerCase(); if (h.length === 3) h = h.split('').map(x => x + x).join(''); return /^[0-9a-f]{6}$/.test(h) ? '#' + h : null; }
